cat << 'EOF' > /app/generate.js
const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({
    viewport: { width: 1200, height: 1600 },
    deviceScaleFactor: 2 // High res screenshot
  });

  const fileUrl = 'file://' + path.resolve(__dirname, 'poster.html');
  await page.goto(fileUrl, { waitUntil: 'networkidle' });

  // wait a bit for fonts to fully load just in case
  await page.waitForTimeout(1000);

  await page.screenshot({ path: '/app/output/final_poster.png' });

  await browser.close();
})();
EOF
NODE_PATH=$(npm root -g) node /app/generate.js
